package app

import (
	"bytes"
	"context"
	"crypto/hmac"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"encoding/xml"
	"fmt"
	"net/http"
	"strings"
	"time"
)

// Sitemap segments (PRD §36).
var SitemapSegments = []string{"pages", "podcasts", "episodes", "categories", "hosts", "collections"}

type sitemapURL struct {
	Loc     string
	LastMod *time.Time
	Freq    string
	Prio    string
}

func xmlEsc(s string) string {
	var b bytes.Buffer
	xml.EscapeText(&b, []byte(s))
	return b.String()
}

// Sitemap renders the sitemap index ("index") or a segment for a tenant (cached; regenerated by worker).
func (a *App) Sitemap(ctx context.Context, tenantID int64, segment string) ([]byte, error) {
	key := fmt.Sprintf("%ssitemap:%s", tenantPrefix(tenantID), segment)
	if b, ok := a.Cache.GetBytes(ctx, key); ok {
		return b, nil
	}
	b, err := a.buildSitemap(ctx, tenantID, segment)
	if err != nil {
		return nil, err
	}
	a.Cache.SetBytes(ctx, key, b, time.Hour)
	return b, nil
}

// GenerateSitemaps rebuilds and caches every sitemap segment for a tenant (GENERATE_SITEMAP job).
func (a *App) GenerateSitemaps(ctx context.Context, tenantID int64) error {
	for _, seg := range append([]string{"index"}, SitemapSegments...) {
		b, err := a.buildSitemap(ctx, tenantID, seg)
		if err != nil {
			return err
		}
		a.Cache.SetBytes(ctx, fmt.Sprintf("%ssitemap:%s", tenantPrefix(tenantID), seg), b, time.Hour)
	}
	return nil
}

func (a *App) buildSitemap(ctx context.Context, tenantID int64, segment string) ([]byte, error) {
	base := a.SiteBaseURL(ctx, tenantID)
	seo, _ := a.SEOSettings(ctx, tenantID)
	var b strings.Builder
	b.WriteString(`<?xml version="1.0" encoding="UTF-8"?>` + "\n")
	if segment == "index" {
		b.WriteString(`<sitemapindex xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">` + "\n")
		now := time.Now().UTC().Format(time.RFC3339)
		for _, s := range SitemapSegments {
			fmt.Fprintf(&b, "  <sitemap><loc>%s/sitemap-%s.xml</loc><lastmod>%s</lastmod></sitemap>\n", xmlEsc(base), s, now)
		}
		b.WriteString("</sitemapindex>\n")
		return []byte(b.String()), nil
	}

	var urls []sitemapURL
	if seo == nil || seo.IndexPolicy != "noindex" {
		var err error
		urls, err = a.sitemapURLs(ctx, tenantID, base, segment)
		if err != nil {
			return nil, err
		}
	}
	b.WriteString(`<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">` + "\n")
	for _, u := range urls {
		b.WriteString("  <url><loc>" + xmlEsc(u.Loc) + "</loc>")
		if u.LastMod != nil {
			b.WriteString("<lastmod>" + u.LastMod.UTC().Format(time.RFC3339) + "</lastmod>")
		}
		if u.Freq != "" {
			b.WriteString("<changefreq>" + u.Freq + "</changefreq>")
		}
		if u.Prio != "" {
			b.WriteString("<priority>" + u.Prio + "</priority>")
		}
		b.WriteString("</url>\n")
	}
	b.WriteString("</urlset>\n")
	return []byte(b.String()), nil
}

// canonicalHere excludes syndicated podcasts whose canonical page lives on another tenant (PRD §38).
const canonicalHere = `NOT EXISTS (SELECT 1 FROM tenant_podcasts tp WHERE tp.tenant_id=$1 AND tp.podcast_id=p.id
	AND tp.canonical_mode='PRIMARY' AND COALESCE(p.canonical_tenant_id, p.owner_tenant_id, $1) <> $1)`

func (a *App) sitemapURLs(ctx context.Context, tenantID int64, base, segment string) ([]sitemapURL, error) {
	var urls []sitemapURL
	collect := func(sql, prefix, freq, prio string, args ...any) error {
		rows, err := a.DB.Query(ctx, sql, args...)
		if err != nil {
			return err
		}
		defer rows.Close()
		for rows.Next() {
			var path string
			var mod *time.Time
			if err := rows.Scan(&path, &mod); err != nil {
				return err
			}
			urls = append(urls, sitemapURL{Loc: base + prefix + path, LastMod: mod, Freq: freq, Prio: prio})
		}
		return rows.Err()
	}
	visible := `p.status='PUBLISHED' AND p.id IN (SELECT podcast_id FROM tenant_podcast_ids($1))`
	switch segment {
	case "pages":
		now := time.Now()
		for _, p := range []struct{ path, prio string }{{"/", "1.0"}, {"/podcasts", "0.8"}, {"/episodes", "0.8"},
			{"/categories", "0.6"}, {"/hosts", "0.5"}, {"/collections", "0.5"}, {"/about", "0.3"}} {
			urls = append(urls, sitemapURL{Loc: base + p.path, LastMod: &now, Freq: "daily", Prio: p.prio})
		}
	case "podcasts":
		return urls, collect(`SELECT p.slug, GREATEST(p.updated_at, COALESCE((SELECT max(published_at) FROM episodes WHERE podcast_id=p.id AND status='PUBLISHED'), p.updated_at))
			FROM podcasts p WHERE `+visible+` AND `+canonicalHere+` ORDER BY p.id`, "/podcast/", "daily", "0.9", tenantID)
	case "episodes":
		return urls, collect(`SELECT p.slug || '/' || e.slug, e.updated_at FROM episodes e JOIN podcasts p ON p.id=e.podcast_id
			WHERE `+visible+` AND `+canonicalHere+` AND e.status='PUBLISHED' AND e.published_at<=now() AND e.canonical_url=''
			ORDER BY e.published_at DESC LIMIT 45000`, "/podcast/", "weekly", "0.7", tenantID)
	case "categories":
		return urls, collect(`SELECT c.slug, NULL::timestamptz FROM categories c WHERE EXISTS (
			SELECT 1 FROM podcasts p LEFT JOIN tenant_podcasts tp ON tp.podcast_id=p.id AND tp.tenant_id=$1
			WHERE `+visible+` AND (c.id IN (p.category_id, p.subcategory_id) OR c.id = tp.category_id))
			ORDER BY c.sort_order`, "/category/", "weekly", "0.6", tenantID)
	case "hosts":
		return urls, collect(`SELECT h.slug, h.updated_at FROM hosts h WHERE EXISTS (
			SELECT 1 FROM podcast_hosts ph JOIN podcasts p ON p.id=ph.podcast_id WHERE ph.host_id=h.id AND `+visible+`)
			ORDER BY h.id`, "/host/", "monthly", "0.5", tenantID)
	case "collections":
		return urls, collect(`SELECT slug, updated_at FROM collections WHERE tenant_id=$1 AND is_published ORDER BY sort_order`,
			"/collection/", "weekly", "0.6", tenantID)
	default:
		return nil, fmt.Errorf("unknown sitemap segment")
	}
	return urls, nil
}

// RevalidateWeb asks the Next.js web app to drop its data cache for a tenant (PRD §85 cache purge).
func (a *App) RevalidateWeb(ctx context.Context, tenantID int64) error {
	body, _ := json.Marshal(map[string]any{"tags": []string{fmt.Sprintf("tenant-%d", tenantID)}})
	req, _ := http.NewRequestWithContext(ctx, http.MethodPost, a.Cfg.WebInternalURL+"/api/revalidate", bytes.NewReader(body))
	req.Header.Set("Content-Type", "application/json")
	req.Header.Set("X-Revalidate-Secret", a.Cfg.RevalidateSecret)
	resp, err := (&http.Client{Timeout: 10 * time.Second}).Do(req)
	if err != nil {
		return err
	}
	resp.Body.Close()
	if resp.StatusCode >= 400 {
		return fmt.Errorf("revalidate: HTTP %d", resp.StatusCode)
	}
	return nil
}

// DeliverWebhook POSTs a signed event payload (PRD §105).
func (a *App) DeliverWebhook(ctx context.Context, webhookID int64, event string, data any, occurredAt time.Time) error {
	var url, secret string
	if err := a.DB.QueryRow(ctx, `SELECT url, secret FROM webhooks WHERE id=$1 AND is_active`, webhookID).Scan(&url, &secret); err != nil {
		return nil // webhook removed/disabled
	}
	payload, _ := json.Marshal(map[string]any{"event": event, "data": data, "occurred_at": occurredAt})
	mac := hmac.New(sha256.New, []byte(secret))
	mac.Write(payload)
	req, err := http.NewRequestWithContext(ctx, http.MethodPost, url, bytes.NewReader(payload))
	if err != nil {
		return err
	}
	req.Header.Set("Content-Type", "application/json")
	req.Header.Set("User-Agent", "PodcastEngine-Webhooks/1.0")
	req.Header.Set("X-Podcast-Event", event)
	req.Header.Set("X-Podcast-Signature", "sha256="+hex.EncodeToString(mac.Sum(nil)))
	resp, err := a.HTTP.Do(req)
	status, errMsg := 0, ""
	if err != nil {
		errMsg = err.Error()
	} else {
		status = resp.StatusCode
		resp.Body.Close()
	}
	ok := err == nil && status < 300
	a.DB.Exec(ctx, `INSERT INTO webhook_deliveries(webhook_id, event, payload, status_code, success, error) VALUES ($1,$2,$3,$4,$5,$6)`,
		webhookID, event, payload, status, ok, errMsg)
	if !ok {
		return fmt.Errorf("webhook delivery failed: status=%d %s", status, errMsg)
	}
	return nil
}
